namespace SrpLab;
public sealed class ScoreLedger { private readonly Dictionary<string,List<decimal>> _scores=new(StringComparer.OrdinalIgnoreCase); public void Record(string id,decimal score){if(score is <0 or >100)throw new ArgumentOutOfRangeException(nameof(score));if(!_scores.TryGetValue(id,out var list)){list=new List<decimal>();_scores[id]=list;}list.Add(score);} public IReadOnlyList<decimal> Get(string id){return _scores.TryGetValue(id,out var list)?list:new List<decimal>();} public IEnumerable<string> StudentIds(){return _scores.Keys;} }
public sealed class GradeAverageCalculator { public decimal Calculate(IReadOnlyList<decimal> scores){return scores.Count==0?0m:Math.Round(scores.Average(),2);} }
public sealed class LetterGradePolicy { public string Get(decimal average){return average>=90?"A":average>=80?"B":average>=70?"C":average>=60?"D":"F";} }
public sealed class HonorRollPolicy { public bool Meets(decimal average,string letter){return average>=85&&(letter=="A"||letter=="B");} }
public sealed class TranscriptFormatter { public string Format(string id,string name,decimal average,string letter,bool honor){return $"TRANSCRIPT\nStudent: {name} ({id})\nAverage: {average}\nLetter: {letter}\nHonor: {honor}\n";} }
public sealed class GradeBookCsvExporter { public string Export(IEnumerable<string> ids,Func<string,decimal> average,Func<string,string> letter,Func<string,bool> honor){var rows=new List<string>{"studentId,average,letter,honor"};foreach(var id in ids.OrderBy(x=>x))rows.Add($"{id},{average(id)},{letter(id)},{(honor(id)?1:0)}");return string.Join('\n',rows);} }
